#include "color_picker_scheme.h"
#include <iostream>
#include <stdexcept>
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
using namespace moon;
int main(){try{CHECK(parseColorPickerScheme("normal-map")==ColorPickerScheme::NormalMap);CHECK(parseColorPickerScheme("moon-ring")==ColorPickerScheme::SvSquare);CHECK(pickerNormalMapColorAt(0,0)==0xffff8080);CHECK(pickerNormalMapColorAt(1,0)==0xff0080ff&&pickerNormalMapColorAt(-1,0)==0xff008000);CHECK(pickerNormalMapColorAt(0,1)==0xff000080&&pickerNormalMapColorAt(0,-1)==0xff00ff80);CHECK(pickerNormalMapBeginHit(1,.5)&&!pickerNormalMapBeginHit(0,0));CHECK(!pickerNormalMapRasterColor(1,.5));CHECK(pickerNormalMapRasterColor(.5,.5)==0xffff8080);CHECK(pickerNormalMapInputColor(3,.5,55)==0x370080ff);PickerRole role;role.color=0x37000000;role.hsv={0,0,1};role.emit();pickerSchemeSetField(role,ColorPickerScheme::NormalMap,.75,.5);CHECK(role.color==0x37dd80bf);auto h=role.hsv.h,s=role.hsv.s;pickerSchemeSetStripValue(role,ColorPickerScheme::NormalMap,0);role.sync(role.color);CHECK(role.color==0x37000000);pickerSchemeSetStripValue(role,ColorPickerScheme::NormalMap,1000);CHECK(role.hsv.h==h&&role.hsv.s==s&&(role.color>>24)==55);auto marker=pickerNormalMapMarker(pickerRgbToHsv(0xffff8080));CHECK(std::abs(marker.first-(1./255+128./255*(1-2./255)))<1e-11);std::cout<<"Normal-map fixtures passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
